export const useSubmitRequest = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof submitRequest>>, TError,{id: number;data: BodyType<SubmissionInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof submitRequest>>,
        TError,
        {id: number;data: BodyType<SubmissionInput>},
        TContext
      > => {
      return useMutation(getSubmitRequestMutationOptions(options));
    }

